fun maxNonOverlapping(intervals: Array<IntArray>): Int {
    intervals.sortBy { it[1] }                    // earliest finish first
    var count = 0
    var lastEnd = Int.MIN_VALUE
    for ((start, end) in intervals) {
        if (start >= lastEnd) {                   // does not overlap the last chosen one
            count++
            lastEnd = end
        }
    }
    return count
}
// Time: O(n log n)   Space: O(1) extra
// Sorting by start time or by length can fail on simple counterexamples

fun fractionalKnapsack(values: IntArray, weights: IntArray, capacity: Int): Double {
    val order = values.indices.sortedByDescending { values[it].toDouble() / weights[it] }
    var remaining = capacity.toDouble()
    var total = 0.0
    for (i in order) {
        if (remaining <= 0) break
        val take = minOf(remaining, weights[i].toDouble())     // a whole item or the fraction that fits
        total += values[i] * (take / weights[i])
        remaining -= take
    }
    return total
}
// Time: O(n log n)   Space: O(n)
// Greedy is optimal for the FRACTIONAL knapsack but NOT for the 0/1 knapsack (use DP)

import java.util.PriorityQueue

fun maxEvents(events: Array<IntArray>): Int {
    events.sortBy { it[0] }                       // by start day
    val endDays = PriorityQueue<Int>()            // events we could attend today, earliest deadline on top
    var day = 0
    var i = 0
    var attended = 0

    while (i < events.size || endDays.isNotEmpty()) {
        if (endDays.isEmpty()) day = events[i][0]                       // jump to the next start
        while (i < events.size && events[i][0] <= day) {                // add everything that has started
            endDays.add(events[i][1])
            i++
        }
        while (endDays.isNotEmpty() && endDays.peek() < day) endDays.poll()   // drop expired events
        if (endDays.isNotEmpty()) {
            endDays.poll()                                              // attend the one ending soonest
            attended++
            day++
        }
    }
    return attended
}
// Time: O(n log n)   Space: O(n)

fun canJump(nums: IntArray): Boolean {
    var farthest = 0
    for (i in nums.indices) {
        if (i > farthest) return false            // a gap: position i can never be reached
        farthest = maxOf(farthest, i + nums[i])
        if (farthest >= nums.size - 1) return true
    }
    return true
}
// Time: O(n)   Space: O(1)

fun candy(ratings: IntArray): Int {
    val n = ratings.size
    val candies = IntArray(n) { 1 }                          // everyone gets at least one
    for (i in 1 until n) {                                   // left to right: compare with the left neighbor
        if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1
    }
    for (i in n - 2 downTo 0) {                              // right to left: compare with the right neighbor
        if (ratings[i] > ratings[i + 1]) candies[i] = maxOf(candies[i], candies[i + 1] + 1)
    }
    return candies.sum()
}
// Time: O(n)   Space: O(n)

fun leastInterval(tasks: CharArray, n: Int): Int {
    val freq = IntArray(26)
    for (t in tasks) freq[t - 'A']++
    val maxFreq = freq.max()                                  // use maxOrNull()!! on Kotlin before 1.7
    val countMax = freq.count { it == maxFreq }
    // (maxFreq - 1) full cycles of length n + 1, plus the final row of the most frequent tasks
    return maxOf(tasks.size, (maxFreq - 1) * (n + 1) + countMax)
}
// Time: O(tasks)   Space: O(1)
// If the formula is smaller than the task count, there is no idle time

// Coins {1, 3, 4}, amount 6
// Greedy picks 4 + 1 + 1 = 3 coins
// Optimal is 3 + 3 = 2 coins

fun coinChangeGreedy(coins: IntArray, amount: Int): Int {
    var remaining = amount
    var count = 0
    for (coin in coins.sortedDescending()) {
        count += remaining / coin
        remaining %= coin
    }
    return if (remaining == 0) count else -1
}
// Correct only for canonical systems such as {1, 5, 10, 25}
// For arbitrary coins use dynamic programming

fun jump(nums: IntArray): Int {
    var jumps = 0
    var currentEnd = 0                             // farthest index reachable with 'jumps' jumps
    var farthest = 0                               // farthest index reachable with one more jump
    for (i in 0 until nums.size - 1) {
        farthest = maxOf(farthest, i + nums[i])
        if (i == currentEnd) {                     // must jump now to go any further
            jumps++
            currentEnd = farthest
        }
    }
    return jumps
}
// Time: O(n)   Space: O(1)
// This is BFS by levels, done without a queue

fun canCompleteCircuit(gas: IntArray, cost: IntArray): Int {
    var total = 0                                  // net gas over the whole circuit
    var tank = 0                                   // net gas since the candidate start
    var start = 0
    for (i in gas.indices) {
        val diff = gas[i] - cost[i]
        total += diff
        tank += diff
        if (tank < 0) {                            // cannot reach i + 1 from the current start
            start = i + 1                          // so no start between them works either
            tank = 0
        }
    }
    return if (total >= 0) start else -1
}
// Time: O(n)   Space: O(1)

fun maxProfit(prices: IntArray): Int {
    var profit = 0
    for (i in 1 until prices.size) {
        if (prices[i] > prices[i - 1]) {
            profit += prices[i] - prices[i - 1]    // collect every upward step
        }
    }
    return profit
}
// Time: O(n)   Space: O(1)

fun partitionLabels(s: String): List<Int> {
    val last = IntArray(26)
    for (i in s.indices) last[s[i] - 'a'] = i      // last position of every letter

    val result = mutableListOf<Int>()
    var start = 0
    var end = 0
    for (i in s.indices) {
        end = maxOf(end, last[s[i] - 'a'])         // the part must extend to cover this letter
        if (i == end) {                            // no letter in this part appears later
            result.add(end - start + 1)
            start = i + 1
        }
    }
    return result
}
// Time: O(n)   Space: O(1)

fun numRescueBoats(people: IntArray, limit: Int): Int {
    people.sort()
    var l = 0
    var r = people.size - 1
    var boats = 0
    while (l <= r) {
        if (people[l] + people[r] <= limit) l++    // the lightest person fits with the heaviest
        r--                                        // the heaviest always takes a boat
        boats++
    }
    return boats
}
// Time: O(n log n)   Space: O(1)

fun twoCitySchedCost(costs: Array<IntArray>): Int {
    costs.sortBy { it[0] - it[1] }                 // how much cheaper A is than B
    val half = costs.size / 2
    var total = 0
    for (i in costs.indices) {
        total += if (i < half) costs[i][0] else costs[i][1]    // most A-favoring people go to A
    }
    return total
}
// Time: O(n log n)   Space: O(1) extra

import java.util.PriorityQueue

fun minRefuelStops(target: Int, startFuel: Int, stations: Array<IntArray>): Int {
    val fuelHeap = PriorityQueue<Int>(compareByDescending { it })   // fuel from stations already passed
    var fuel = startFuel.toLong()
    var stops = 0
    var i = 0
    while (fuel < target) {
        while (i < stations.size && stations[i][0] <= fuel) {
            fuelHeap.add(stations[i][1])                             // stations we could have stopped at
            i++
        }
        if (fuelHeap.isEmpty()) return -1                            // stuck
        fuel += fuelHeap.poll()                                      // refuel retroactively at the biggest one
        stops++
    }
    return stops
}
// Time: O(n log n)   Space: O(n)

fun reconstructQueue(people: Array<IntArray>): Array<IntArray> {
    // tallest first; for equal heights, fewer people in front first
    people.sortWith(compareBy({ -it[0] }, { it[1] }))
    val result = ArrayList<IntArray>()
    for (p in people) {
        result.add(p[1], p)                        // insert at index k: shorter people placed later do not matter
    }
    return result.toTypedArray()
}
// Time: O(n²) because of the inserts   Space: O(n)

fun lemonadeChange(bills: IntArray): Boolean {
    var five = 0
    var ten = 0
    for (b in bills) {
        when (b) {
            5 -> five++
            10 -> {
                if (five == 0) return false
                five--
                ten++
            }
            else -> {                              // 20: prefer giving a 10 and a 5, keep the more flexible 5s
                if (ten > 0 && five > 0) { ten--; five-- }
                else if (five >= 3) five -= 3
                else return false
            }
        }
    }
    return true
}
// Time: O(n)   Space: O(1)

fun checkValidString(s: String): Boolean {
    var low = 0                                    // fewest possible open parentheses
    var high = 0                                   // most possible open parentheses
    for (c in s) {
        when (c) {
            '(' -> { low++; high++ }
            ')' -> { low--; high-- }
            else -> { low--; high++ }              // '*' can be ')', empty or '('
        }
        if (high < 0) return false                 // too many closing parentheses even in the best case
        low = maxOf(low, 0)                        // we cannot have a negative number of open ones
    }
    return low == 0
}
// Time: O(n)   Space: O(1)

import java.util.TreeMap

fun isNStraightHand(hand: IntArray, groupSize: Int): Boolean {
    if (hand.size % groupSize != 0) return false
    val count = TreeMap<Int, Int>()
    for (card in hand) count[card] = (count[card] ?: 0) + 1

    while (count.isNotEmpty()) {
        val first = count.firstKey()               // the smallest card must start a group
        for (card in first until first + groupSize) {
            val c = count[card] ?: return false
            if (c == 1) count.remove(card) else count[card] = c - 1
        }
    }
    return true
}
// Time: O(n log n)   Space: O(n)

fun maximumUnits(boxTypes: Array<IntArray>, truckSize: Int): Int {
    boxTypes.sortByDescending { it[1] }            // most units per box first
    var remaining = truckSize
    var units = 0
    for ((boxes, perBox) in boxTypes) {
        val take = minOf(remaining, boxes)
        units += take * perBox
        remaining -= take
        if (remaining == 0) break
    }
    return units
}
// Time: O(n log n)   Space: O(1) extra

// Smallest number after removing k digits: remove a digit when the next digit is smaller.
fun removeKdigits(num: String, k: Int): String {
    val stack = StringBuilder()
    var remaining = k
    for (c in num) {
        while (remaining > 0 && stack.isNotEmpty() && stack.last() > c) {
            stack.deleteCharAt(stack.length - 1)   // a larger digit before a smaller one is wasteful
            remaining--
        }
        stack.append(c)
    }
    while (remaining > 0 && stack.isNotEmpty()) {
        stack.deleteCharAt(stack.length - 1)
        remaining--
    }
    val result = stack.toString().trimStart('0')
    return if (result.isEmpty()) "0" else result
}
// Time: O(n)   Space: O(n)
// Greedy choice: make the leftmost digit as small as possible
